const strategies = new Map([
  ['local', new LocalStrategy(async (username, password, cb) => {
      const user = await users.find(username);
      if (!user) return cb(null, false);                        // invalid credentials
      const ok = await verify(password, user.passwordHash);      // scrypt/PBKDF2 + timingSafeEqual
      cb(null, ok ? user : false);
  })],
  ['bearer', new BearerStrategy(async (token, cb) => cb(null, await introspect(token) || false))],
]);

const strategy = strategies.get(config.scheme);
if (!strategy) throw new Error(`unknown authentication scheme: ${config.scheme}`);
passport.use(strategy);
app.post('/login', passport.authenticate(config.scheme, { session: true }), handler);
